/* eslint-disable max-len */

'use strict';

// MODULES //

var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var setReadOnlyAccessor = require( '@stdlib/utils/define-nonenumerable-read-only-accessor' );
var setReadWriteAccessor = require( '@stdlib/utils/define-nonenumerable-read-write-accessor' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var isObject = require( '@stdlib/assert/is-plain-object' );
var isBoolean = require( '@stdlib/assert/is-boolean' ).isPrimitive;
var FLOAT64_MAX_SAFE_INTEGER = require( '@stdlib/constants/float64/max-safe-integer' );
var isPositiveInteger = require( '@stdlib/assert/is-positive-integer' ).isPrimitive;
var isUint32Array = require( '@stdlib/assert/is-uint32array' );
var format = require( '@stdlib/string/format' );
var Uint32Array = require( '@stdlib/array/uint32' );
var UINT32_MAX = require( '@stdlib/constants/uint32/max' );
var gcopy = require( '@stdlib/blas/base/gcopy' );
var randint32 = require( './rand_int32.js' );


// VARIABLES //

// Define the state array schema version:
var STATE_ARRAY_VERSION = 1;

// Define the number of sections in the state array:
var STATE_ARRAY_SIZE = 3; // [version, state, seed]

// Define the index offset of the "version" in the state array:
var VERSION_INDEX = 0;

// Define the index offset of the "state" in the state array:
var STATE_INDEX = 1;

// Define the index offset of the "seed" in the state array:
var SEED_INDEX = 2;

var MAX_SEED = UINT32_MAX >>> 0;

// Normalization constant for float64 with 53-bit precision:
var FLOAT64_NORM_CONSTANT = 1.0 / (FLOAT64_MAX_SAFE_INTEGER + 1.0);

// Maximum normalized value (53-bit precision):
var MAX_NORMALIZED = FLOAT64_MAX_SAFE_INTEGER * FLOAT64_NORM_CONSTANT;


// FUNCTIONS //

/**
* Verifies state array integrity.
*
* @private
* @param {UInt32ArrayInt32Array} state - state array
* @param {boolean} isOption - indicating whether the state array was provided as an option (true) or an argument (false)
* @returns {(Error|null)} an error or `null`
*/
function verifyState(state, isOption) {
	var typeStr = ( isOption ) ? 'option' : 'argument';

	// Check minimum length...
	if (state.length !== STATE_ARRAY_SIZE) {
		return new RangeError(format('invalid %s. State array must have length %u. Actual: %u.', typeStr, STATE_ARRAY_SIZE, state.length));
	}
	// The first element of the state array must equal the supported state array schema version...
	if (state[VERSION_INDEX] !== STATE_ARRAY_VERSION) {
		return new RangeError(format('invalid %s. State array has an incompatible schema version. Expected: %u. Actual: %u.', typeStr, STATE_ARRAY_VERSION, state[VERSION_INDEX]));
	}
	// Check state is non-zero (XORShift requirement)
	if (state[STATE_INDEX] === 0) {
		return new RangeError(format('invalid %s. XORShift state must be non-zero.', typeStr));
	}
	// Check seed is non-zero (helps catch initialization errors)
	if (state[SEED_INDEX] === 0) {
		return new RangeError(format('invalid %s. XORShift seed must be non-zero.', typeStr));
	}
	return null;
}
/**
* Returns the PRNG state length.
*
* @private
* @returns {PositiveInteger} state length
* */
function getStateLength() {
	return STATE_ARRAY_SIZE;
}

/**
* Returns the PRNG state length.
*
* @private
* @returns {PositiveInteger} state length
* */
function getSeedLength() {
	return 1;
}


// MAIN //

/**
* Returns a xorshift32 pseudorandom number generator.
*
* @param {Object} [options] - function options
* @param {PositiveInteger} [options.seed] - pseudorandom number generator seed on the interval `[1, 4294967295]`
* @param {Uint32Array} [options.state] - pseudorandom number generator state; if provided, the seed option is ignored
* @param {boolean} [options.copy=true] - boolean indicating whether to copy a provided state array; if false, allows sharing state between generators
* @throws {TypeError} options must be an object
* @throws {TypeError} options.seed must be a positive integer
* @throws {RangeError} options.seed must be on the interval `[1, 4294967295]`
* @throws {TypeError} options.state must be a Uint32Array
* @throws {Error} options.state must be a valid state array
* @throws {TypeError} options.copy must be a boolean
* @returns {Function} pseudorandom number generator
*
* @example
* var xorshift32 = factory();
*
* var v = xorshift32();
* // returns <number>
*
* @example
* // Create a generator with a specific seed
* var xorshift32 = factory( { 'seed': 1234 } );
* var v = xorshift32();
* // returns 332584831
*
* @example
* // Create a generator with a specific state
* var state = new Uint32Array( [ 1, 12345, 12345 ] );
* var xorshift32 = factory( { 'state': state } );
* var v = xorshift32();
* // returns <number>
*/
function factory(options) {
	var STATE;
	var state;
	var opts;
	var seed;
	var err;
	var tmp;

	opts = {};
	if (arguments.length) {
		if (!isObject(options)) {
			throw new TypeError(format('invalid argument. Options argument must be an object. Value: %s.', options));
		}
		if (hasOwnProp(options, 'copy')) {
			opts.copy = options.copy;
			if (!isBoolean(options.copy)) {
				throw new TypeError(format('invalid option. %s option must be a boolean. Option: %s.', 'copy', options.copy));
			}
		}
		if (hasOwnProp(options, 'state')) {
			state = options.state;
			opts.state = true;
			if (!isUint32Array(state)) {
				throw new TypeError(format('invalid option. %s option must be an UInt32Array. Option: %s.', 'state', state));
			}
			err = verifyState(state, true);
			if (err) {
				throw err;
			}
			// Copy state if requested
			if ( opts.copy !== false ) {
				tmp = new Uint32Array( STATE_ARRAY_SIZE );
				gcopy( STATE_ARRAY_SIZE, state, 1, tmp, 1 );
				STATE = tmp;
			} else {
				STATE = state;
			}
		}
		// If provided a PRNG state, we ignore the seed option...
		if (STATE === void 0) {
			if (hasOwnProp(options, 'seed')) {
				seed = options.seed;
				opts.seed = true;

				// Check if it's a positive integer FIRST
				if (!isPositiveInteger(seed)) {
					// If not positive integer, check if it's zero (special case)
					if (seed === 0) {
						throw new RangeError(format('invalid option. %s option must be non-zero. Option: %u.', 'seed', seed));
					}
					// Otherwise it's a type error (not a positive integer)
					throw new TypeError(format('invalid option. %s option must be a positive integer. Option: %s.', 'seed', seed));
				}

				// CORRECTION: Check range BEFORE coercion to uint32
				// This ensures we catch overflow values before they wrap around
				if (seed > MAX_SEED) {
					throw new RangeError(format('invalid option. %s option must be less than or equal to %u. Option: %u.', 'seed', MAX_SEED, seed));
				}

				// Coerce to uint32 AFTER validation
				seed >>>= 0;
			}
		} else {
			seed = randint32() >>> 0; // asm type annotation
			if (seed === 0) {
				seed = 1;
			}
		}
	}

	if (seed === void 0) {
		seed = randint32() >>> 0;
		if (seed === 0) {
			seed = 1;
		}
	}

	if (STATE === void 0) {
		STATE = new Uint32Array(STATE_ARRAY_SIZE);
		STATE[VERSION_INDEX] = STATE_ARRAY_VERSION;
		STATE[STATE_INDEX] = seed >>> 0;
		STATE[SEED_INDEX] = seed >>> 0;
	}

	/**
* Returns the PRNG state length.
*
* @private
* @returns {Uint32Array} seed array
* */
	function getSeed() {
		var out = new Uint32Array(1);
		out[0] = STATE[SEED_INDEX];
		return out;
	}

	/**
* Returns the PRNG state size (in bytes).
*
* @private
* @returns {PositiveInteger} state size (in bytes)
* */
	function getStateSize() {
		return STATE.byteLength;
	}

	/**
* Returns a copy of current PRNG state.
*
* ## Notes
*
* -   The state array has a length 3: [ version, state, seed ]
* -   Modifiying the returned array does not effect the generator state unless the array is explicitly set via setState()
*
* @private
* @returns {Uint32Array} state array copy
* */
	function getState() {
		var out = new Uint32Array(STATE_ARRAY_SIZE);
		gcopy(STATE_ARRAY_SIZE, STATE, 1, out, 1);
		return out;
	}

	/**
* Sets the PRNG state.
*
* ## Notes
*
* -   If PRNG state is "shared" (meaning a state array was provided during PRNG creation and _not_ copied) and one sets the generator state to a state array having a different length, the PRNG does _not_ update the existing shared state and, instead, points to the newly provided state array. In order to synchronize PRNG output according to the new shared state array, the state array for _each_ relevant PRNG must be _explicitly_ set.
* -   If PRNG state is "shared" and one sets the generator state to a state array of the same length, the PRNG state is updated (along with the state of all other PRNGs sharing the PRNG's state array).
*
* @private
* @param {Uint32Array} s - generator state
* @throws {TypeError} must provide an UInt32Array
* @throws {Error} must provide a valid state
* */
	function setState(s) {
		var err;
		if (!isUint32Array(s)) {
			throw new TypeError(format('invalid argument. Must provide an Uint32Array. Value: %s.', s));
		}
		err = verifyState(s, false);
		if (err) {
			throw err;
		}
		if ( opts.copy === false ) {
			// Shared state case
			if ( opts.state && s.length === STATE_ARRAY_SIZE ) {
				// Update existing shared state
				gcopy( STATE_ARRAY_SIZE, s, 1, STATE, 1 );
			} else {
				// Point to new shared state
				STATE = s;
				opts.state = true;
			}
		} else {
			// Owned state case
			if ( s.length !== STATE_ARRAY_SIZE ) {
				// Reallocate if size mismatch
				STATE = new Uint32Array( STATE_ARRAY_SIZE );
			}
			gcopy( STATE_ARRAY_SIZE, s, 1, STATE, 1 );
		}
	}

	/**
* Serializes the pseudorandom number generator as a JSON object.
*
* ## Notes
*
* -   JSON.stringify() implicitly calls this method when stringifying a PRNG.
*
* @private
* @returns {Object} JSON representation
* */
	function toJSON() {
		var out = {};
		var i;
		out.type = 'PRNG';
		out.name = xorshift32.NAME;
		out.state = [];
		for ( i = 0; i < STATE.length; i++) {
			out.state.push( STATE[i] );
		}
		out.params = [];
		return out;
	}

	/**
* Generates a pseudorandom unsigned 32-bit integer.
*
* @private
* @returns {Uint32} pseudorandom integer
* */
	function xorshift32() {
		var x = STATE[STATE_INDEX] | 0; // asm type annotation
		x ^= x << 13; // xorshift step 1
		x ^= x >>> 17; // xorshift step 2
		x ^= x << 5; // xorshift step 3
		STATE[STATE_INDEX] = x; // store updated state
		return x >>> 0;
	}

	/**
* Generates a pseudorandom number on the interval \\( [0,1) \\).
*
* @private
* @returns {number} pseudorandom number
* */
	function normalized() {
		return (xorshift32() >>> 5) * FLOAT64_NORM_CONSTANT;
	}

	// NOW set properties on the PRNG function (after it's defined)
	setReadOnly(xorshift32, 'NAME', 'xorshift32');
	setReadOnlyAccessor(xorshift32, 'seed', getSeed);
	setReadOnlyAccessor(xorshift32, 'seedLength', getSeedLength);
	setReadWriteAccessor(xorshift32, 'state', getState, setState);
	setReadOnlyAccessor(xorshift32, 'stateLength', getStateLength);
	setReadOnlyAccessor(xorshift32, 'byteLength', getStateSize);
	setReadOnly(xorshift32, 'toJSON', toJSON);
	setReadOnly(xorshift32, 'MIN', 0);
	setReadOnly(xorshift32, 'MAX', UINT32_MAX);
	setReadOnly(xorshift32, 'normalized', normalized);

	setReadOnly(normalized, 'NAME', xorshift32.NAME);
	setReadOnlyAccessor(normalized, 'seed', getSeed);
	setReadOnlyAccessor(normalized, 'seedLength', getSeedLength);
	setReadWriteAccessor(normalized, 'state', getState, setState);
	setReadOnlyAccessor(normalized, 'stateLength', getStateLength);
	setReadOnlyAccessor(normalized, 'byteLength', getStateSize);
	setReadOnly(normalized, 'toJSON', toJSON);
	setReadOnly(normalized, 'MIN', 0.0);
	setReadOnly(normalized, 'MAX', MAX_NORMALIZED);

	return xorshift32;
}


// EXPORTS //

module.exports = factory;
